	newest := commit.Committer.When.UTC()

	// Walk parents to find the oldest commit in this generation
	iter := commit
	for len(iter.ParentHashes) > 0 {
		parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
		if parentErr != nil {
			break
