435	// rotateGeneration archives the current /full/current generation and creates
436	// a fresh orphan. This is a 2-phase operation:
437	//
438	//  1. Archive: determine the next generation number, create a new ref pointing
439	//     to the current /full/current commit.
440	//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
441	//     point /full/current at it.
442	func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
443		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
444	
445		// Guard against concurrent rotation: re-read /full/current and check if
446		// it's still above the threshold. If not, another instance already rotated.
447		_, currentTreeHash, err := s.GetRefState(refName)
448		if err != nil {
449			return fmt.Errorf("rotation: failed to read /full/current: %w", err)
450		}
451		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
452		if err != nil {
453			return fmt.Errorf("rotation: failed to count checkpoints: %w", err)
454		}
455		if checkpointCount < s.maxCheckpoints() {
456			return nil
457		}
458	
459		currentRef, err := s.repo.Reference(refName, true)
460		if err != nil {
461			return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
462		}
463	
464		archiveNumber, err := s.nextGenerationNumber()
465		if err != nil {
466			return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
467		}
468	
469		// Phase 1: Archive — create ref pointing to the current commit.
470		// If the archive ref already exists, another instance already rotated — skip.
471		archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
472		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
473			logging.Info(ctx, "rotation: archive ref already exists, skipping",
474				slog.String("archive_ref", string(archiveRefName)),
475			)
476			return nil
477		}
478		archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
479		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
480			return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
481		}
482	
483		// Verify /full/current hasn't been advanced by another writer since we read it.
484		// If it changed, abort — the archive ref is harmless (points to a valid commit)
485		// and the next writer will trigger rotation again.
486		postArchiveRef, err := s.repo.Reference(refName, true)
487		if err != nil {
488			return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
489		}
490		if postArchiveRef.Hash() != currentRef.Hash() {
491			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
492			return nil
493		}
494	
495		// Write generation.json to the current tree before archiving.
496		gen := s.computeGenerationTimestamps(currentTreeHash)
497		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
498		if err != nil {
499			return fmt.Errorf("rotation: failed to add generation.json: %w", err)
500		}
501	
502		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
503		archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
504		if err != nil {
505			return fmt.Errorf("rotation: failed to create archive commit: %w", err)
506		}
507	
508		// Update the archive ref to point to the commit with generation.json
509		archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
510		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
511			return fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
512		}
513	
514		// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
515		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
516		if err != nil {
517			return fmt.Errorf("rotation: failed to build empty tree: %w", err)
518		}
519	
